files.content:
body {
  margin: 0;
  font-family: Arial, sans-serif;
  background: #f9f6f1;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #3d3030;
  color: #ffffff;
  padding: 10px 30px;
}

nav a {
  color: #ffffff;
  margin-left: 20px;
  text-decoration: none;
}

nav a:hover {
  color: #f2c6a5;
}

.banner {
  background: #e07b60;
  color: #ffffff;
  text-align: center;
  padding: 60px 20px;
}

.banner h2 {
  font-size: 44px;
  margin: 0;
}

.cards {
  display: flex;
  gap: 20px;
  padding: 40px 30px;
}

.card {
  flex: 1;
  background: #ffffff;
  border: 1px solid #d9d4cd;
  border-radius: 12px;
  padding: 15px;
  color: gray;
}

.card h3 {
  color: #3d3030;
}

.picture {
  background: #f2c6a5;
  height: 120px;
  border-radius: 8px;
}

footer {
  background: #3d3030;
  color: #ffffff;
  text-align: center;
  padding: 15px;
}

